// Response-window observer, one instance per obligation, generated by tsec.
// Latency is counted in clock cycles from the first cycle in which the trigger
// input shows its new value to the first cycle in which the response output does.
// The two assumptions are the environment side of the contract: the trigger is
// preceded by QUIET stable cycles and held until the response. A trigger counts
// only while en holds (the program is at the wait the obligation belongs to).
// abandon ends an armed check without a response: the program left every path
// from the wait to the acting instruction (a guard chose another branch, or an
// abort), so the obligation does not apply to this trigger.
module tse_window_check #(
  parameter int LO    = 0,
  parameter int HI    = 8,
  parameter int QUIET = 8,
  parameter int W     = 8
) (
  input logic clk,
  input logic rst,
  input logic en,
  input logic trig_in,
  input logic trig_val,
  input logic resp_out,
  input logic resp_val,
  input logic abandon
);
  logic in_q, out_q, armed;
  logic [W-1:0] age, quiet;
  wire trig = trig_in == trig_val && in_q != trig_val;
  wire resp = resp_out == resp_val && out_q != resp_val;

  always_ff @(posedge clk) begin
    in_q  <= trig_in;
    out_q <= resp_out;
    if (rst || trig_in != in_q) quiet <= '0;
    else if (quiet != '1) quiet <= quiet + W'(1);
    if (rst) begin
      armed <= 1'b0;
      age   <= '0;
    end else if (trig && en && !armed) begin
      armed <= 1'b1;
      age   <= W'(1);
    end else if (armed && resp) begin
      armed <= 1'b0;
    end else if (armed && abandon) begin
      armed <= 1'b0;
    end else if (armed) begin
      age <= age + W'(1);
    end
  end

  always_comb begin
    if (!rst) begin
      if (trig && en && !armed) assume (quiet >= W'(QUIET));
      if (armed) assume (trig_in == trig_val);
      if (armed && resp) assert (age >= W'(LO) && age <= W'(HI));
      if (armed) assert (age <= W'(HI));     // the deadline cannot pass silently
    end
  end

  always @(posedge clk) if (!rst) cover (armed && resp);   // non-vacuity: a response happens
endmodule
